#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S. Import NumLoops.NDig.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := S1Layout.
Abbreviation SEGS := Plain.M.loaded_segments.

Definition DP_RET_SNP : Z := 0x9dfb8.
Definition DPL_RET_SNP : Z := 0x9da8c.

Section DoPut.
  Context {fx : FPState}.
Context {RRND : RunRandom}.
  Variables (R : bvmap 5 word) (M : mem) (ssp ds v fl ret : Z) (fillw : word).
  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 ssp.
  Hypothesis Htp : getr R 4%bv = Z_to_bv 64 (ly_tp Ly.L).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (ds + 8).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 (ds + 112).
  Hypothesis Ha3 : getr R 13%bv = fillw.
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis Hslo : 2 ^ 32 <= ssp - 1520.
  Hypothesis Hshi : ssp < 2 ^ 47.
  Hypothesis Hal : ssp mod 16 = 0.
  Hypothesis HD : mdef M (ssp - 1520) 1520.
  Hypothesis Hds : 2 ^ 16 <= ds /\ ds + 392 <= 2 ^ 47 /\ ds mod 8 = 0.
  Hypothesis DJds : ds + 392 <= ssp - 1520 \/ ssp <= ds.
  Hypothesis Gfl : fld SEGS M (ds + 120) 4 fl.
  Hypothesis Hfl : fl = DS_FL0 \/ fl = DS_FLHEX.
  Hypothesis Gloc : fld SEGS M (ds + 160) 8 LOC_IMP.
  Hypothesis Gwidth : fld SEGS M (ds + 136) 8 0.
  Hypothesis Gvsb : fld SEGS M (ds + 8) 8 VT_SB.
  Hypothesis PINS : pins D_DIAG M.
  Hypothesis ROC : ro_clear Ly.L M.
  Hypothesis RRC : relro_clear M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 rr_canary.

  #[local] Notation dpm := (DoPutDefs.dpm R M ssp ds ret fillw 0x9e090).
  #[local] Notation dps := (DoPutDefs.dps R M ssp ds ret fillw).

  Lemma doput_back : forall nc R2 M2, dps nc R2 M2 ->
